import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address _owner) public {
        // The setOwner caller must be the admin (msg.sender == deployer of C).
        // The fuzzer provides any address for the new owner.
