pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address admin, address newOwner) public {
        vm.assume(admin != address(0));
        vm.assume(newOwner != address(0));
        vm.assume(admin != c.owner());

        // deploy a fresh C with admin as the deployer
        vm.prank(admin);
        C c2 = new C();

        // admin calls setOwner
        vm.prank(admin);
        c2.setOwner(newOwner);

        // the invariant: after admin sets a new owner, the owner must be updated
        assertTrue(c2.owner() == newOwner);
    }
}

