pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address newOwner) public {
        // The original admin is address(this) because setUp() deploys c.
        // The admin calls setOwner with a fuzzed newOwner.
        bool success;
        try c.setOwner(newOwner) returns (bool) {
            success = true;
        } catch {
            success = false;
        }
        // In the reference contract, the admin call succeeds.
        // In the buggy contract, the admin call reverts (because msg.sender != owner).
        // Therefore, after a successful call, owner must equal newOwner.
        assertTrue(!success || c.owner() == newOwner);
    }
}

